import type { LightingModel, Params } from './params';

export type ThemeName = 'light' | 'dark';

interface Theme {
  /** SVG background-pattern base colour. */
  patternBg: string;
  /** SVG background-pattern lattice/dot colour. */
  patternShape: string;
  boidColorX: string;
  boidColorY: string;
  boidColorZ: string;
  /** Which boid shading model the theme selects. */
  lighting: LightingModel;
}

export const LIGHT_THEME: Theme = {
  patternBg: '#fff5f5',
  patternShape: '#ffe492',
  boidColorX: '#A3B7DF',
  boidColorY: '#182143',
  boidColorZ: '#0b1322',
  lighting: 'world'
};

export const DARK_THEME: Theme = {
  patternBg: '#001d2c',
  patternShape: '#123b52',
  boidColorX: '#00f03c',
  boidColorY: '#0b1322',
  boidColorZ: '#5b86d7',
  lighting: 'local'
};

/**
 * Applies a theme: flips the `data-theme` attribute (the SVG pattern colours are
 * driven by CSS vars) and writes the boid palette into `params` in place, which
 * the renderer reads every frame. No further refresh is needed.
 */
export function applyTheme(name: ThemeName, params: Params): void {
  const theme = name === 'dark' ? DARK_THEME : LIGHT_THEME;
  document.documentElement.dataset.theme = name;
  params.boidColorX = theme.boidColorX;
  params.boidColorY = theme.boidColorY;
  params.boidColorZ = theme.boidColorZ;
  params.lighting = theme.lighting;
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.setAttribute('content', theme.patternBg);
}

/** Wires the top-left toggle button, starting in the light theme. */
export function initTheme(params: Params, button: HTMLButtonElement): void {
  let theme: ThemeName = 'light';
  applyTheme(theme, params);
  button.addEventListener('click', () => {
    theme = theme === 'light' ? 'dark' : 'light';
    applyTheme(theme, params);
    button.setAttribute('aria-pressed', theme === 'dark' ? 'true' : 'false');
  });
}
