import { parseConfig, type BoidsConfig } from './config/schema';
import { MOBILE_DEFAULTS, detectMobile } from './platform';
import { DEFAULT_PARAMS, type Params } from './params';
import presetJson from './config/preset.json';

export interface Preset {
  /** Whether the coarse mobile/tablet heuristics matched. */
  mobile: boolean;
  config: BoidsConfig;
  params: Params;
}

/**
 * Loads the bundled preset, overlaying the cheaper mobile defaults when on a
 * small device, and expands it into a full `Params` object. Shared by the
 * viewer and preset entry points.
 */
export function loadPreset(): Preset {
  const mobile = detectMobile();
  const parsed = parseConfig(JSON.stringify(presetJson));
  const config: BoidsConfig = mobile
    ? { ...parsed, params: { ...parsed.params, ...MOBILE_DEFAULTS } }
    : parsed;
  const params: Params = { ...DEFAULT_PARAMS, ...config.params };
  return { mobile, config, params };
}
