import { bootstrap } from './boot';
import { loadPreset } from './preset';
import { initTheme } from './theme';

const { mobile, config, params } = loadPreset();

bootstrap({
  params,
  ui: false,
  interactive: false,
  antialias: !mobile,
  transparent: true,
  configure: (app) => app.applyConfig(config)
});

const themeToggle = document.getElementById('themeToggle') as HTMLButtonElement | null;
if (themeToggle) initTheme(params, themeToggle);
